@once
<style>
.referral-ui{font-family:Inter,system-ui,sans-serif;color:#203c30;font-size:14px;line-height:1.55;min-width:0}.referral-ui *{box-sizing:border-box}.referral-ui h1{font-size:24px;line-height:1.3;margin:0 0 6px;font-weight:700}.referral-ui h2,.referral-ui h3{font-size:17px;margin:0 0 8px;font-weight:650}.referral-ui p{margin:0 0 12px}.referral-ui .ru-muted{color:#687b72;font-size:13px}.referral-ui .ru-card{background:#fff;border:1px solid #e0e9e3;border-radius:16px;padding:20px;margin:16px 0}.referral-ui .ru-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.referral-ui .ru-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}.referral-ui button,.referral-ui .ru-button{font:600 13px Inter,system-ui,sans-serif;padding:10px 16px;min-height:42px;border:1px solid #bcd8c7;border-radius:9px;background:#fff;color:#087642;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.referral-ui button[type=submit],.referral-ui button[value=confirmed]{background:#07964e;color:#fff;border-color:#07964e}.referral-ui button:disabled{opacity:.55;cursor:default}.referral-ui label{display:block;font-size:13px;font-weight:600}.referral-ui input,.referral-ui select,.referral-ui textarea{display:block;width:100%;min-width:0;margin:6px 0 12px;padding:11px;border:1px solid #ccd9d1;border-radius:9px;background:#fff;font:inherit;color:inherit}.referral-ui textarea{min-height:90px}.referral-ui dt{font-size:12px;color:#687b72;margin-bottom:5px}.referral-ui dd{margin:0;font-weight:600;overflow-wrap:anywhere}.referral-ui .ru-field{padding:14px;background:#f5f9f6;border-radius:10px}.referral-ui .ru-entry{border-top:1px solid #e5ece7;padding:18px 0}.referral-ui :focus-visible{outline:2px solid #08964e;outline-offset:3px}@media(max-width:600px){.referral-ui .ru-grid{grid-template-columns:1fr}.referral-ui .ru-card{padding:16px}.referral-ui h1{font-size:20px}.referral-ui .ru-actions>*{flex:1 1 auto}}
</style>
@endonce
